CREATE TYPE public.app_role AS ENUM ('super_admin','admin','lead_manager','sales_executive','store_manager','funding_manager','global_manager','content_editor','hr_manager','viewer','partner');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role public.app_role NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,role));
GRANT SELECT,INSERT,DELETE ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE FUNCTION public.is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('super_admin','admin')) $$;
CREATE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id) $$;
CREATE FUNCTION public.can_manage_leads(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('super_admin','admin','lead_manager','viewer')) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin(auth.uid())); CREATE POLICY grant_roles ON public.user_roles FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'super_admin')); CREATE POLICY revoke_roles ON public.user_roles FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'super_admin'));
CREATE TABLE public.profiles(id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,email text NOT NULL,full_name text,created_at timestamptz NOT NULL DEFAULT now(),approval_status text NOT NULL DEFAULT 'pending' CHECK(approval_status IN('pending','approved','rejected')),reviewed_at timestamptz);
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_profiles ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_staff(auth.uid())); CREATE POLICY edit_profiles ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'super_admin')) WITH CHECK(id=auth.uid() OR public.has_role(auth.uid(),'super_admin'));
CREATE FUNCTION public.protect_approval_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (NEW.approval_status IS DISTINCT FROM OLD.approval_status OR NEW.email IS DISTINCT FROM OLD.email) AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'super_admin') THEN RAISE EXCEPTION 'Only the Super Admin can change approval or identity'; END IF; IF NEW.approval_status IS DISTINCT FROM OLD.approval_status THEN NEW.reviewed_at:=now(); END IF; RETURN NEW; END $$;
CREATE TRIGGER profiles_protect_approval BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.protect_approval_status();
CREATE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,email,full_name) VALUES(NEW.id,NEW.email,NEW.raw_user_meta_data->>'full_name') ON CONFLICT(id) DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),lead_type text NOT NULL,name text NOT NULL,company text,phone text NOT NULL,email text NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,message text,source_page text,status text NOT NULL DEFAULT 'new',assigned_to uuid,notes text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.leads TO anon,authenticated; GRANT SELECT,UPDATE,DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role; ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY submit_lead ON public.leads FOR INSERT TO anon,authenticated WITH CHECK(lead_type IN('manufacturer','retailer','distributor','funding','global','general','contact') AND char_length(name) BETWEEN 2 AND 120 AND char_length(email) BETWEEN 5 AND 200 AND char_length(phone) BETWEEN 7 AND 20 AND coalesce(char_length(message),0)<=4000 AND status='new');
CREATE POLICY read_leads ON public.leads FOR SELECT TO authenticated USING(public.can_manage_leads(auth.uid()) OR assigned_to=auth.uid()); CREATE POLICY update_leads ON public.leads FOR UPDATE TO authenticated USING((public.can_manage_leads(auth.uid()) AND NOT public.has_role(auth.uid(),'viewer')) OR assigned_to=auth.uid()) WITH CHECK((public.can_manage_leads(auth.uid()) AND NOT public.has_role(auth.uid(),'viewer')) OR assigned_to=auth.uid()); CREATE POLICY delete_leads ON public.leads FOR DELETE TO authenticated USING(public.is_admin(auth.uid()));
CREATE TABLE public.lead_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),lead_id uuid NOT NULL REFERENCES public.leads(id) ON DELETE CASCADE,user_id uuid NOT NULL DEFAULT auth.uid(),kind text NOT NULL DEFAULT 'note',body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT ON public.lead_activities TO authenticated; GRANT ALL ON public.lead_activities TO service_role; ALTER TABLE public.lead_activities ENABLE ROW LEVEL SECURITY; CREATE POLICY read_activities ON public.lead_activities FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id)); CREATE POLICY write_activities ON public.lead_activities FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.leads WHERE id=lead_id));
CREATE TABLE public.employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id text NOT NULL UNIQUE,employee_code text NOT NULL,full_name text NOT NULL,designation text NOT NULL,department text NOT NULL,work_location text NOT NULL,date_of_joining date,official_email text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),user_id uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role; ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY; CREATE POLICY employee_read ON public.employees FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'hr_manager')); CREATE POLICY employee_manage ON public.employees FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'hr_manager')) WITH CHECK(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'hr_manager'));
CREATE TABLE public.directory_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('investor','mentor','team')),slug text NOT NULL,data jsonb NOT NULL DEFAULT '{}'::jsonb,sort_order int NOT NULL DEFAULT 0,is_published boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,slug)); GRANT SELECT ON public.directory_profiles TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.directory_profiles TO authenticated; GRANT ALL ON public.directory_profiles TO service_role; ALTER TABLE public.directory_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY directory_read ON public.directory_profiles FOR SELECT TO anon,authenticated USING(is_published OR public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor') OR(kind='team' AND public.has_role(auth.uid(),'hr_manager'))); CREATE POLICY directory_manage ON public.directory_profiles FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor') OR(kind='team' AND public.has_role(auth.uid(),'hr_manager'))) WITH CHECK(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor') OR(kind='team' AND public.has_role(auth.uid(),'hr_manager')));
CREATE TABLE public.site_content(key text PRIMARY KEY CHECK(key IN('services','countries','faq','pricing')),data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid DEFAULT auth.uid()); GRANT SELECT ON public.site_content TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_content TO authenticated; GRANT ALL ON public.site_content TO service_role; ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY; CREATE POLICY content_read ON public.site_content FOR SELECT TO anon,authenticated USING(true); CREATE POLICY content_manage ON public.site_content FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor')) WITH CHECK(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor'));
CREATE TABLE public.stores(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,state text NOT NULL,area text,district text,address text,phone text,store_type text NOT NULL DEFAULT 'retail',is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.stores TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.stores TO authenticated; GRANT ALL ON public.stores TO service_role; ALTER TABLE public.stores ENABLE ROW LEVEL SECURITY; CREATE POLICY stores_read ON public.stores FOR SELECT TO anon,authenticated USING(is_active OR public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'store_manager')); CREATE POLICY stores_manage ON public.stores FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'store_manager')) WITH CHECK(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'store_manager'));
CREATE TABLE public.staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,lead_types text[] NOT NULL DEFAULT '{}',states text[] NOT NULL DEFAULT '{}',priority integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.staff_assignments TO authenticated; GRANT ALL ON public.staff_assignments TO service_role; ALTER TABLE public.staff_assignments ENABLE ROW LEVEL SECURITY; CREATE POLICY assignments_read ON public.staff_assignments FOR SELECT TO authenticated USING(public.can_manage_leads(auth.uid()) OR user_id=auth.uid()); CREATE POLICY assignments_manage ON public.staff_assignments FOR ALL TO authenticated USING(public.can_manage_leads(auth.uid()) AND NOT public.has_role(auth.uid(),'viewer')) WITH CHECK(public.can_manage_leads(auth.uid()) AND NOT public.has_role(auth.uid(),'viewer'));
CREATE TABLE public.announcements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,body text NOT NULL,audience text NOT NULL DEFAULT 'all',published_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.announcements TO authenticated; GRANT ALL ON public.announcements TO service_role; ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY; CREATE POLICY announcements_read ON public.announcements FOR SELECT TO authenticated USING(true); CREATE POLICY announcements_manage ON public.announcements FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor')) WITH CHECK(public.is_admin(auth.uid()) OR public.has_role(auth.uid(),'content_editor'));
CREATE FUNCTION public.auto_assign_lead() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE st text; assignee uuid; BEGIN st:=coalesce(NEW.details->>'state',''); SELECT a.user_id INTO assignee FROM public.staff_assignments a WHERE(cardinality(a.lead_types)=0 OR NEW.lead_type=ANY(a.lead_types)) AND(cardinality(a.states)=0 OR st=ANY(a.states)) ORDER BY a.priority DESC LIMIT 1; NEW.assigned_to:=assignee; RETURN NEW; END $$; CREATE TRIGGER leads_auto_assign BEFORE INSERT ON public.leads FOR EACH ROW EXECUTE FUNCTION public.auto_assign_lead();